-- Seed batch 3 (21 Sep 2026): Google Trends keyword data (digipincode) -
-- all uploaded CSVs parsed: top/rising, 3-month + daily, deduped.
-- volume = Trends interest (0-100 proxy, NOT GSC impressions).
-- Upsert: existing curated keywords keep notes, volume/priority update.
ON CONFLICT(site, keyword) DO UPDATE SET
  volume=excluded.volume, priority=excluded.priority,
  updated_at=datetime('now');
